mapper.select:
SELECT * FROM (
  SELECT qno, qtitle, qdate, qstatus
  FROM question
  ORDER BY qno DESC
)
WHERE ROWNUM <= #{limit}

SELECT * FROM (
  SELECT qno, qtitle, qdate, qstatus
  FROM question
  WHERE mno = #{mno}
  ORDER BY qno DESC
)
WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE question
SET
    qtitle = #{qtitle},
    qcontent = #{qcontent}
WHERE qno = #{qno}
